// 1. Obtém os dados do Webhook
const webhookData = $('Webhook Clientes').first().json.body;
let clientes = [];

if (webhookData && Array.isArray(webhookData.clientes)) {
  clientes = webhookData.clientes;
} else if (Array.isArray(webhookData)) {
  clientes = webhookData;
} else if (webhookData && typeof webhookData === 'object') {
  clientes = [webhookData];
}

// 2. Obtém o CSV de investimentos
const csvRaw = $input.first().json.data || $input.first().json;
const csvTexto = typeof csvRaw === 'string' ? csvRaw : (csvRaw.body || '');

const linhasCsv = csvTexto.trim().split(/\r?\n/);
const investimentos = [];
for (let i = 1; i < linhasCsv.length; i++) {
  const cols = linhasCsv[i].split(',').map(c => c.trim());
  if (cols.length >= 4) {
    investimentos.push({
      perfil: cols[0],
      produto: cols[1],
      minimo: parseFloat(cols[2]) || 0,
      rentabilidade: cols[3]
    });
  }
}

function parseSaldo(saldoStr) {
  if (typeof saldoStr === 'number') return saldoStr;
  if (!saldoStr) return 0;
  const limpo = saldoStr.toString().replace('R$', '').replace(/\s/g, '').replace(/\./g, '').replace(',', '.');
  return parseFloat(limpo) || 0;
}

// 3. Cruzamento de clientes x investimentos
const resultado = clientes.map(cliente => {
  const saldoNum = cliente.saldo_numerico !== undefined ? cliente.saldo_numerico : parseSaldo(cliente.saldo);

  const produtosPerfil = investimentos.filter(inv => 
    inv.perfil.toLowerCase() === (cliente.perfil || '').toLowerCase()
  );

  const produtosAcessiveis = produtosPerfil.filter(inv => saldoNum >= inv.minimo);
  const produtosFinais = produtosAcessiveis.length > 0 ? produtosAcessiveis : produtosPerfil;

  // Monta lista de produtos como texto
  const produtosTexto = produtosFinais.map(p => 
    `- ${p.produto}: Aporte minimo R$ ${p.minimo.toLocaleString('pt-BR')}, Rentabilidade ${p.rentabilidade}`
  ).join('\n');

  // Monta o prompt completo
  const promptText = `Voce e um assessor de investimentos experiente e atencioso da DIO Bank.

Dados do Cliente:
- Nome: ${cliente.nome}
- Perfil de Risco: ${cliente.perfil}
- Saldo em Conta: ${cliente.saldo}

Opcoes de Investimento Compativeis:
${produtosTexto}

Tarefa:
Escreva uma mensagem de assessoria financeira humanizada, empatica e encorajadora para ${cliente.nome}.
1. Cumprimente-o pelo nome e comente brevemente sobre a postura do perfil ${cliente.perfil}.
2. Apresente as opcoes recomendadas com seus aportes minimos e rentabilidades de forma clara e organizada.
3. De uma dica estrategica de educacao financeira personalizada para o momento dele.
4. Conclua com uma despedida calorosa convidando para conversar.

Seja profissional, amigavel e direto ao ponto.`;

  // Monta o corpo completo da requisicao ao Gemini
  const geminiBody = {
    contents: [
      {
        parts: [
          {
            text: promptText
          }
        ]
      }
    ],
    generationConfig: {
      temperature: 0.7,
      maxOutputTokens: 600
    }
  };

  return {
    cliente: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      saldo_numerico: saldoNum,
      perfil: cliente.perfil
    },
    produtos_recomendados: produtosFinais,
    geminiBody: geminiBody
  };
});

return resultado.map(item => ({ json: item }));

// Extrai o texto gerado pelo Gemini e consolida os dados do cliente
const itens = $input.all();
const itensAnteriores = $('Cruzar Clientes x Investimentos').all();

return itens.map((item, index) => {
  const dadosCliente = itensAnteriores[index] ? itensAnteriores[index].json : {};
  const respostaGemini = item.json;

  let mensagemIA = '';
  try {
    mensagemIA = respostaGemini.candidates[0].content.parts[0].text;
  } catch (err) {
    mensagemIA = 'Nao foi possivel gerar a mensagem com IA no momento. Verifique sua chave GEMINI_API_KEY.';
  }

  return {
    json: {
      cliente_nome: dadosCliente.cliente ? dadosCliente.cliente.nome : 'Cliente',
      cliente_email: dadosCliente.cliente ? dadosCliente.cliente.email : '',
      perfil: dadosCliente.cliente ? dadosCliente.cliente.perfil : '',
      saldo: dadosCliente.cliente ? dadosCliente.cliente.saldo : '',
      produtos_recomendados: dadosCliente.produtos_recomendados || [],
      recomendacao_ia_gemini: mensagemIA,
      provedor_ia: 'Google Gemini 1.5 Flash',
      timestamp: new Date().toISOString()
    }
  };
});
